return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'he_IL','project-id-version'=>'Babilim 1.2.1','pot-creation-date'=>'2026-11-09T07:54:20+00:00','po-revision-date'=>'2026-11-09T07:54:20+00:00','x-generator'=>'Babilim','messages'=>['Sent when you press Enable Babilim, and again if the site has to register anew: your site\'s URL, the WordPress, PHP and Babilim versions, the language of your site and the languages in use on it, and a public key generated for this site.'=>'נשלח כשאתה לוחץ על הפעלת Babilim, ושוב אם האתר צריך להירשם מחדש: כתובת ה-URL של האתר שלך, גרסאות WordPress, PHP ו-Babilim, שפת האתר שלך והשפות בשימוש בו, ומפתח ציבורי שנוצר עבור אתר זה.','Sent on every check: the list of installed plugins and themes with the state of any Babilim translation installed for them, the languages in use, and short diagnostic codes.'=>'נשלח בכל בדיקה: רשימת התוספים והתבניות המותקנים יחד עם מצב כל תרגום של Babilim שמותקן עבורם, השפות בשימוש, וקודי אבחון קצרים.','Every request includes your site\'s URL, and the site\'s access token is included whenever the service needs it.'=>'כל בקשה כוללת את כתובת ה-URL של האתר שלך, ואסימון הגישה של האתר נכלל בכל פעם שהשירות זקוק לו.','What Babilim sends to the service'=>'מה Babilim שולח לשירות','Your site\'s URL'=>'כתובת ה-URL של האתר שלך','WordPress version'=>'גרסת WordPress','PHP version'=>'גרסת PHP','Babilim version'=>'גרסת Babilim','Your site\'s language'=>'שפת האתר שלך','Languages in use on your site'=>'שפות בשימוש באתר שלך','A public key for this site'=>'מפתח ציבורי עבור אתר זה','A public key generated for this site, used to prove requests genuinely come from this site. Only the public half is ever sent; the private half stays on your site.'=>'מפתח ציבורי שנוצר עבור אתר זה, ומשמש להוכחה שהבקשות אכן מגיעות מהאתר הזה. רק החלק הציבורי נשלח אי פעם; החלק הפרטי נשאר באתר שלך.','Installed plugins and themes'=>'תוספים ותבניות מותקנים','For every installed plugin and theme: its name (slug), version, text domain, whether it is listed on WordPress.org, and the languages it already includes. For each Babilim translation you have installed: which version it is, when it was last checked, and whether it passed its file check.'=>'עבור כל תוסף ותבנית מותקנים: השם שלו (slug), הגרסה, ה-text domain, האם הוא רשום ב-WordPress.org, והשפות שהוא כבר כולל. עבור כל תרגום של Babilim שהתקנת: איזו גרסה הוא, מתי נבדק לאחרונה, והאם עבר את בדיקת הקבצים שלו.','Source files (only if you confirm an upload)'=>'קובצי מקור (רק אם אישרת העלאה)','Diagnostic codes'=>'קודי אבחון','Up to 20 short diagnostic codes (for example, a translation file that failed its check), each with the plugin or theme, the language and the time it happened. They never contain any text from your site or any translated text.'=>'עד 20 קודי אבחון קצרים (לדוגמה, קובץ תרגום שנכשל בבדיקה), כל אחד עם התוסף או התבנית, השפה והזמן שבו זה קרה. הם לעולם אינם מכילים טקסט כלשהו מהאתר שלך או טקסט מתורגם כלשהו.','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'%1$d אתר ברשת זו מוגדר למחוק את זהות Babilim שלו כאשר התוסף נמחק. לא ניתן יהיה לשחזר אוטומטית את הרישיון בתשלום המקושר לאתר הזה; יהיה עליך לפנות לתמיכה של Babilim בכתובת %2$s. כדי לשמור על הזהות, לחץ על ביטול, בטל את הסימון של "מחק את כל נתוני Babilim בעת הסרת ההתקנה" בהגדרות Babilim של האתר הזה, והשבת שוב. להשבית בכל זאת?' . "\0" . '%1$d אתרים ברשת זו מוגדרים למחוק את זהות Babilim שלהם כאשר התוסף נמחק. לא ניתן יהיה לשחזר אוטומטית את הרישיון בתשלום המקושר לאתרים האלה; יהיה עליך לפנות לתמיכה של Babilim בכתובת %2$s. כדי לשמור על הזהויות, לחץ על ביטול, בטל את הסימון של "מחק את כל נתוני Babilim בעת הסרת ההתקנה" בהגדרות Babilim של כל אתר, והשבת שוב. להשבית בכל זאת?','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','%1$s nothing to do.'=>'%1$s אין מה לעשות.','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. יש לבחור את השפה.','%d failed'=>'%d נכשלו' . "\0" . '%d נכשלו','%d not yet tried'=>'%d טרם נוסו' . "\0" . '%d טרם נוסו','%d report is waiting. "Always share" and "Don\'t share" apply to all of them.'=>'דוח %d ממתין. "לשתף תמיד" ו"לא לשתף" חלים על כולם.' . "\0" . '%d דוחות ממתינים. "לשתף תמיד" ו"לא לשתף" חלים על כולם.','%d skipped'=>'%d דולגו' . "\0" . '%d דולגו','%d succeeded'=>'%d הצליחו' . "\0" . '%d הצליחו','%d to install'=>'%d להתקנה' . "\0" . '%d להתקנה','(a public key generated for this site)'=>'(מפתח ציבורי שנוצר עבור האתר הזה)','(detected)'=>'(זוהה)','(generic codes and coordinates only)'=>'(קודים וקואורדינטות כלליים בלבד)','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'ניקוי הושהה ב-%1$s: %2$s. דבר לא נמחק.','A file in the component could not be read, so it was not packaged.'=>'לא ניתן היה לקרוא קובץ ברכיב, ולכן הוא לא נארז.','A host that serves only one PHP request at a time cannot complete this step.'=>'אחסון שמטפל בבקשת PHP אחת בלבד בכל פעם לא יכול להשלים שלב זה.','A part of the upload kept failing, so the upload was cancelled.'=>'חלק מההעלאה נכשל שוב ושוב, ולכן ההעלאה בוטלה.','A translation cannot be requested for that locale on this site right now.'=>'לא ניתן לבקש תרגום לשפה זו באתר הזה כרגע.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'כתיבה לאינדקס התרגומים התנגשה בבקשה אחרת ב-%1$s (%2$s) ולא הוחלה; הגרסה העדכנית ביותר נשמרה.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'לא ניתן היה להשלים כתיבה לאינדקס התרגומים ב-%1$s (%2$s) והיא לא הוחלה (%3$s).','Account'=>'חשבון','Add another language'=>'הוספת שפה נוספת','Advanced'=>'מתקדם','All'=>'הכול','All free-plan slots for this site are used'=>'כל המשבצות בתוכנית החינמית עבור אתר זה בשימוש','All languages'=>'כל השפות','Already in WordPress core'=>'כבר קיים בליבת WordPress','Already installed.'=>'כבר מותקן.','Always share'=>'לשתף תמיד','Another installation is running; try again in a moment.'=>'התקנה אחרת מתבצעת כעת; נסה שוב בעוד רגע.','Automatic installs'=>'התקנות אוטומטיות','Automatic installs are now off; turn them on again in the settings if you want them.'=>'ההתקנות האוטומטיות כבויות כעת; ניתן להפעיל אותן שוב בהגדרות אם תרצה.','Available'=>'זמין','Available translations can be installed with one click, and missing ones can be requested. While automatic installs are on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'אפשר להתקין תרגומים זמינים בלחיצה אחת, ולבקש תרגומים חסרים. כשההתקנות האוטומטיות פועלות, תרגומים שהשירות מציין כזמינים עבור השפות שבהן אתה משתמש מותקנים במהלך סנכרון פעמיים ביום.','Available · %s'=>'זמין · %s','Babilim'=>'Babilim','Babilim Settings'=>'הגדרות Babilim','Babilim adds translations for every language checked here.'=>'Babilim מוסיף תרגומים לכל שפה שמסומנת כאן.','Babilim could not confirm a temporary folder outside the website, so the component was not packaged and nothing was uploaded. Define BABILIM_TEMP_DIR in wp-config.php as a writable folder outside the web root (for example a folder next to, not inside, your site\'s public directory), or ask your host for one.'=>'Babilim לא הצליח לאשר תיקייה זמנית מחוץ לאתר, ולכן הרכיב לא נארז ושום דבר לא הועלה. הגדר את BABILIM_TEMP_DIR בקובץ wp-config.php כתיקייה הניתנת לכתיבה מחוץ לתיקיית השורש של האתר (למשל תיקייה לצד התיקייה הציבורית של האתר שלך ולא בתוכה), או בקש אחת מחברת האחסון.','Babilim could not finish checking this site.'=>'Babilim לא הצליח לסיים את בדיקת האתר הזה.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim לא הצליח להשלים את ההפעלה (%1$s): %2$s','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim לא הצליח להשלים את אימות האתר (השירות לא הצליח לפנות אליו בחזרה). ההרשמה מושהית.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim לא הצליח לאמת את האתר הזה, ולכן דבר לא יורד או מותקן עד שהאימות יצליח.','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim לא הצליח לאמת את האתר הזה, ולכן דבר לא יורד או מותקן.','Babilim gets translations from the Babilim service for the plugins and themes on this site that have none for your language, and installs the ones your service plan covers.'=>'Babilim מקבל תרגומים משירות Babilim עבור התוספים והתבניות באתר זה שאין להם תרגום בשפה שלך, ומתקין את אלה שתוכנית השירות שלך מכסה.','Babilim has not been enabled for this site yet.'=>'Babilim עדיין לא הופעל עבור אתר זה.','Babilim has not installed any translation for this language.'=>'Babilim לא התקין אף תרגום לשפה הזו.','Babilim hit an error. Share an error report?'=>'Babilim נתקל בשגיאה. לשתף דוח שגיאה?','Babilim installed %d translation automatically since your last visit.'=>'Babilim התקין %d תרגום אוטומטית מאז הביקור האחרון שלכם.' . "\0" . 'Babilim התקין %d תרגומים אוטומטית מאז הביקור האחרון שלכם.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim מושבת. לא יישלח עוד דבר; תרגומים שכבר הותקנו ימשיכו לעבוד.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim מופעל: האתר הזה מאומת ונמצא %d רכיב.' . "\0" . 'Babilim מופעל: האתר הזה מאומת ונמצאו %d רכיבים.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim מפעיל ובודק את האתר הזה… (ניסיון אחרון: %s)','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim מפעיל ובודק את האתר הזה… רעננו את העמוד או המתינו לסיום הבדיקה המתוזמנת.','Babilim is not enabled.'=>'Babilim אינו מופעל.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim מוגדר למחוק את זהות האתר הזה כאשר התוסף נמחק. לא ניתן יהיה לשחזר אוטומטית את הרישיון בתשלום המקושר לאתר הזה; יהיה עליך לפנות לתמיכה של Babilim בכתובת %s. כדי לשמור על הזהות, לחץ על ביטול, בטל את הסימון של "מחק את כל נתוני Babilim בעת הסרת ההתקנה" בהגדרות Babilim, והשבת שוב. להשבית בכל זאת?','Babilim ran out of time for this step and will continue on the next check.'=>'הזמן שהוקצב ל־Babilim לשלב זה אזל, והוא ימשיך בבדיקה הבאה.','Babilim settings'=>'הגדרות Babilim','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'הסנכרון של Babilim מושהה זמנית על ידי השירות (הגבלת קצב); הוא ינסה שוב אחרי %s.','Babilim was updated while this upload was waiting. The old package was discarded; please confirm the upload again.'=>'Babilim עודכן בזמן שההעלאה הזו המתינה. החבילה הישנה נמחקה; אשר את ההעלאה שוב.','Babilim will upload these files from %1$s (version %2$s): every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in its main folder. They are used to find the text that needs translating and to identify the plugin or theme.'=>'Babilim יעלה את הקבצים האלה מ-%1$s (גרסה %2$s): כל קובצי ‎.php ו-‎.js, כל קובצי block.json, וכן readme.txt, readme.md, style.css ו-theme.json בתיקייה הראשית שלו. הם משמשים לאיתור הטקסט שצריך לתרגם ולזיהוי התוסף או התבנית.','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest אינו זמין: %s','Back'=>'חזרה','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'רכשת בעבר רישיון לדומיין הזה? הזן את קוד השחזור שקיבלת בעת התשלום.','Broken placeholder'=>'מציין מיקום שבור','Build'=>'גרסת בנייה','Built'=>'נבנה','Bulk actions apply only to the selected language of each selected component.'=>'פעולות קבוצתיות חלות רק על השפה שנבחרה של כל רכיב שנבחר.','Bulk actions apply to every matching language of each selected component.'=>'פעולות קבוצתיות חלות על כל שפה תואמת של כל רכיב שנבחר.','Bulk download:'=>'הורדה קבוצתית:','Bulk request:'=>'בקשה קבוצתית:','Bulk update:'=>'עדכון קבוצתי:','Bundled with the plugin'=>'מצורף לתוסף','Bundled with the theme'=>'מצורף לתבנית','By clicking Enable, you agree to send the information listed above to Babilim.'=>'בלחיצה על הפעלה, אתם מסכימים לשלוח ל-Babilim את המידע המפורט לעיל.','By continuing you confirm that you have the right to upload this component.'=>'בהמשך התהליך אתם מאשרים שיש לכם הזכות להעלות את הרכיב הזה.','Cancel'=>'ביטול','Category'=>'קטגוריה','Check again'=>'בדיקה מחדש','Check again now'=>'בדוק שוב עכשיו','Checkout is not available for this site right now.'=>'התשלום אינו זמין לאתר זה כרגע.','Choose'=>'בחירה','Choose a category…'=>'בחירת קטגוריה…','Choose a language'=>'בחירת שפה','Choose a language…'=>'בחירת שפה…','Clear filters'=>'ניקוי מסננים','Close'=>'סגירה','Component'=>'רכיב','Confirm'=>'אישור','Conflicting keys'=>'מפתחות מתנגשים','Continue'=>'המשך','Continue next batch (%d left)'=>'המשך לאצווה הבאה (נותרו %d)','Continuing…'=>'ממשיך…','Could not back up %s before replacing it.'=>'לא ניתן היה לגבות את %s לפני החלפתו.','Could not create the package archive.'=>'לא ניתן ליצור את ארכיון החבילה.','Could not determine active components; the existing merged index was left unchanged.'=>'לא ניתן היה לקבוע את הרכיבים הפעילים; האינדקס המאוחד הקיים נשאר ללא שינוי.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'לא ניתן לקבוע אילו תוספים/תבניות מותקנים; הסריקה דולגה, דבר לא נמחק.','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'לא ניתן היה לטעון מהשירות את רשימת השפות המלאה של WordPress.org, ולכן אי אפשר להוסיף שפה נוספת כרגע.','Could not move %s into place.'=>'לא ניתן היה להעביר את %s למקומו.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'לא ניתן להעביר למקומו את האינדקס הממוזג עבור \'%s\'; האינדקס שהוגש קודם לכן (אם היה) הוסר במקום להישאר מעודכן למחצה. לא תוגש השלמה לדומיין ברירת המחדל עבור שפה זו עד לבנייה מחדש מוצלחת הבאה.','Could not open zip: %s'=>'לא ניתן היה לפתוח את ה-zip: %s','Could not prepare %s for rollback.'=>'לא ניתן להכין את %s לשחזור לגרסה קודמת.','Could not read %s back after moving it into place.'=>'לא ניתן לקרוא את %s בחזרה לאחר העברתו למקומו.','Could not read: %s'=>'לא ניתן לקרוא: %s','Could not restore the purchase: %s'=>'לא ניתן היה לשחזר את הרכישה: %s','Could not show a new restore code: %s'=>'לא ניתן היה להציג קוד שחזור חדש: %s','Could not stage %s'=>'לא ניתן היה להכין את %s להתקנה','Could not stage default/%s'=>'לא ניתן היה להכין את default/%s להתקנה','Could not start checkout: %s'=>'לא ניתן היה להתחיל את התשלום: %s','Could not verify entry count for %s'=>'לא ניתן היה לאמת את מספר הרשומות עבור %s','Could not write the downloaded package to disk.'=>'לא ניתן היה לכתוב את החבילה שהורדה לדיסק.','Could not write the staged merged index.'=>'לא ניתן לכתוב את האינדקס הממוזג בשלב ביניים.','Current translation'=>'התרגום הנוכחי','Custom overrides'=>'עקיפות מותאמות','Danger zone'=>'אזור מסוכן','Default supplement entry count mismatch.'=>'אי-התאמה במספר הרשומות של תוספת ברירת המחדל.','Delete all Babilim data on uninstall'=>'מחק את כל נתוני Babilim בעת הסרת ההתקנה','Disable Babilim'=>'השבתת Babilim','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'להשבית את Babilim? התרגומים המותקנים נשמרים, אך לא יתבצעו בדיקות או הורדות נוספות.','Don\'t share'=>'לא לשתף','Download'=>'הורדה','Downloaded and installed.'=>'הורד והותקן.','Downloading…'=>'מוריד…','Downloads: %1$d/%2$d (%3$s)'=>'הורדות: %1$d/%2$d (%3$s)','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'התרומה של כל רכיב להשלמה המשותפת לדומיין ברירת המחדל של כל שפה.','Enable Babilim'=>'הפעלת Babilim','Enabling…'=>'מפעיל…','English (United States)'=>'אנגלית (ארצות הברית)','Entries'=>'רשומות','Entry count mismatch for %s'=>'אי-התאמה במספר הרשומות עבור %s','Error reports'=>'דוחות שגיאה','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'כל שפה (locale) בשימוש באתר הזה (שפת האתר, חבילות שפה מותקנות, שפות משתמשים וכל שפה שתוסיף ידנית). אין יחס שונה לאף שפה.','Excluded'=>'לא נכלל','Files with other names or extensions are not included, nor are the uploads, cache, logs, backup, data, vendor, node_modules and languages folders, hidden files, or files whose names match common secrets (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Code files can still contain text or data you would not want to share; check them if you are unsure. The service removes the same kinds of files again on arrival.'=>'קבצים בשמות או בסיומות אחרים אינם נכללים, וכך גם התיקיות uploads, cache, logs, backup, data, vendor, node_modules ו-languages, קבצים מוסתרים, או קבצים ששמותיהם תואמים לסודות נפוצים (wp-config*, .env*, *.sql, *.log, *.pem, *.key). קובצי קוד עדיין עשויים להכיל טקסט או נתונים שלא תרצה לשתף; בדוק אותם אם אינך בטוח. השירות מסיר שוב סוגי קבצים דומים עם הגעתם.','Fills in missing translations for the plugins and themes already installed on your site.'=>'משלים תרגומים חסרים עבור התוספים והתבניות שכבר מותקנים באתר שלך.','Free'=>'חינמי','Free-plan slots'=>'משבצות בתוכנית החינמית','General'=>'כללי','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'אם האפשרות הזו מופעלת, הסרת ההתקנה תמחק גם את זהות האתר הזה. לא ניתן יהיה לשחזר אוטומטית את הרישיון בתשלום המקושר לאתר הזה; יהיה עליך לפנות לתמיכה של Babilim בכתובת %s כדי לקבל אותו בחזרה.','Included'=>'כלול','Included in index'=>'כלול באינדקס','Install available translations automatically'=>'התקן תרגומים זמינים באופן אוטומטי','Installed'=>'מותקן','Installed translations are kept, but no further checks or downloads will run.'=>'התרגומים המותקנים נשמרים, אך לא יתבצעו בדיקות או הורדות נוספות.','Installed · %s'=>'מותקן · %s','Installed · built for %1$s, this site has %2$s'=>'מותקן · נבנה עבור %1$s, באתר זה מותקנת %2$s','Installed · built for %s'=>'מותקן · נבנה עבור %s','Installed · built for %s, new version failed'=>'מותקן · נבנה עבור %s, הגרסה החדשה נכשלה','Installed · built for %s, new version scheduled'=>'מותקן · נבנה עבור %s, גרסה חדשה מתוזמנת','Installed · built for %s, translating the new version…'=>'מותקן · נבנה עבור %s, הגרסה החדשה בתרגום…','Installed · built for %s; this plugin or theme is no longer covered by the site\'s service plan'=>'מותקן · נבנה עבור %s; התוסף או התבנית הזו אינם מכוסים עוד על ידי תוכנית השירות של האתר','Installed · built for a different version'=>'מותקן · נבנה עבור גרסה אחרת','Installed · built for a different version, new version failed'=>'מותקן · נבנה עבור גרסה אחרת, הגרסה החדשה נכשלה','Installed · built for a different version, new version scheduled'=>'מותקן · נבנה עבור גרסה אחרת, גרסה חדשה מתוזמנת','Installed · built for a different version, translating the new version…'=>'מותקן · נבנה עבור גרסה אחרת, הגרסה החדשה בתרגום…','Installed · built for a different version; this plugin or theme is no longer covered by the site\'s service plan'=>'מותקן · נבנה עבור גרסה אחרת; התוסף או התבנית הזו אינם מכוסים עוד על ידי תוכנית השירות של האתר','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'היא נשמרת אצל ספק האחסון של השירות ומעובדת על ידי מודלי בינה מלאכותית כדי להפיק את התרגום.','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'שמירה על עקיפות התרגום שלי בעת ניקוי כל הנתונים או הסרת התקנה של התוסף.','Language'=>'שפה','Language:'=>'שפה:','Languages'=>'שפות','Languages found on this site: %s.'=>'שפות שנמצאו באתר הזה: %s.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'הניקוי האחרון ב-%1$s: %2$d קבצים סומנו לראשונה, %3$d קבצים נמחקו, %4$d רשומות הוסרו.','Maintenance'=>'תחזוקה','Maintenance status is not available right now.'=>'סטטוס התחזוקה אינו זמין כרגע.','Manifest unavailable: %s'=>'ה-manifest אינו זמין: %s','Negation reversed'=>'שלילה הפוכה','No'=>'לא','No build is available to download for this locale.'=>'אין גרסה זמינה להורדה עבור שפה זו.','No cleanup has run yet.'=>'טרם בוצע ניקוי.','No components match these filters. %s'=>'אין רכיבים שתואמים למסננים האלה. %s','No components synced yet.'=>'עדיין לא סונכרנו רכיבים.','No installed translation matches.'=>'אין תרגום מותקן שתואם.','No language is managed yet.'=>'עדיין לא מנוהלת אף שפה.','No pending challenge for this nonce.'=>'אין אתגר ממתין עבור ה-nonce הזה.','No pending challenge to verify.'=>'אין אתגר ממתין לאימות.','No plugins or themes found.'=>'לא נמצאו תוספים או תבניות.','No previous build to roll back to.'=>'אין בנייה קודמת לשחזור אליה.','No record for %s'=>'אין רשומה עבור %s','No site id is on file to rotate a token for.'=>'אין מזהה אתר שמור שעבורו ניתן להחליף אסימון.','No — component inactive'=>'לא — הרכיב אינו פעיל','No — component removed'=>'לא — הרכיב הוסר','No — installed version differs from the active one'=>'לא — הגרסה המותקנת שונה מהגרסה הפעילה','Not a valid server_build_id: %s'=>'server_build_id לא תקין: %s','Not covered by the free service plan'=>'לא כלול בתוכנית השירות החינמית','Not installed'=>'לא מותקן','Not registered yet'=>'טרם נרשם','Not supported'=>'לא נתמך','Not verified'=>'לא אומת','Note (optional)'=>'הערה (אופציונלי)','Nothing to choose.'=>'אין מה לבחור.','Nothing to confirm.'=>'אין מה לאשר.','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'כבוי כברירת מחדל: מחיקת התוסף משמרת את זהות האתר, כך שהתקנה מחדש יכולה להשתמש בה שוב.','One or more served files no longer match the manifest.'=>'קובץ אחד או יותר מהקבצים שהוגשו אינם תואמים עוד ל-manifest.','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'רכישה חד-פעמית עבור האתר הזה: %1$s %2$s. כוללת את כל עדכוני התרגום העתידיים. התשלום מטופל על ידי Paddle בלשונית חדשה.','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'רק מנהל רשת יכול לבצע פעולה זו, מכיוון שהיא משנה קובצי תרגום המשותפים לכל האתרים ברשת.','Only plugins and themes can be packaged.'=>'ניתן לארוז רק תוספים וערכות נושא.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in that component\'s main folder, as a zip, after files that match common secrets are left out.'=>'רק כשתאשר העלאה עבור תוסף או תבנית שאינם ב-WordPress.org: כל קובצי ‎.php ו-‎.js, כל קובצי block.json, וכן readme.txt, readme.md, style.css ו-theme.json בתיקייה הראשית של הרכיב, כקובץ zip, לאחר שקבצים התואמים לסודות נפוצים הוצאו.','Open Babilim settings'=>'פתח את הגדרות Babilim','Original language'=>'שפת מקור','Original string'=>'המחרוזת המקורית','Paid'=>'בתשלום','Partner'=>'שותף','Please check that your site can be reached from the internet, then try again.'=>'אנא ודאו שניתן להגיע לאתר שלכם מהאינטרנט, ולאחר מכן נסו שוב.','Please choose a category for this report.'=>'יש לבחור קטגוריה עבור הדיווח הזה.','Plugin'=>'תוסף','Plugin · %s'=>'תוסף · %s','Plugins'=>'תוספים','Preview'=>'תצוגה מקדימה','Purchase restored. This site is now licensed.'=>'הרכישה שוחזרה. האתר הזה מורשה כעת.','Re-parsed entry count did not match the built index.'=>'מספר הרשומות שנותח מחדש אינו תואם לאינדקס שנבנה.','Re-verify'=>'אימות מחדש','Rebuild index now'=>'בנה את האינדקס מחדש עכשיו','Refusing to write outside the Babilim language-file directory.'=>'מסרב לכתוב מחוץ לספריית קובצי השפה של Babilim.','Registration response was missing required fields.'=>'בתגובת הרישום חסרים שדות נדרשים.','Registration restarted.'=>'ההרשמה התחילה מחדש.','Remove'=>'הסרה','Remove everything Babilim installed'=>'הסרת כל מה ש-Babilim התקין','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'להסיר את כל מה ש-Babilim התקין? פעולה זו תמחק כל קובץ שפה ש-Babilim התקין עבור כל תוסף ותבנית באתר זה.','Remove the %2$s translation of %1$s from this site?'=>'להסיר מהאתר הזה את התרגום %2$s של %1$s?','Removed %d installed component.'=>'הוסר %d רכיב מותקן.' . "\0" . 'הוסרו %d רכיבים מותקנים.','Removed after a failed integrity check'=>'הוסר לאחר שבדיקת תקינות נכשלה','Removed.'=>'הוסר.','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'מסיר כל קובץ שפה ש-Babilim התקין עבור כל תוסף ותבנית באתר זה.','Report a problem'=>'דיווח על בעיה','Report translation'=>'דיווח על תרגום','Request newer translation'=>'בקשת תרגום חדש יותר','Request translation'=>'בקשת תרגום','Requestable'=>'ניתן לבקש','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site (the limit is %1$d for themes and %2$d for plugins), unless it already has one. A slot stays used, and a failed translation does not free it.'=>'בקשת תרגום מציבה את התוסף או התבנית הזו באחת מהמכסות של תוכנית השירות החינמית עבור אתר זה (המגבלה היא %1$d לתבניות ו-%2$d לתוספים), אלא אם כבר יש לה מכסה. המכסה נשארת בשימוש, ותרגום שנכשל אינו משחרר אותה.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site, unless it already has one. A slot stays used, and a failed translation does not free it.'=>'בקשת תרגום מציבה את התוסף או התבנית הזו באחת מהמכסות של תוכנית השירות החינמית עבור אתר זה, אלא אם כבר יש לה מכסה. המכסה נשארת בשימוש, ותרגום שנכשל אינו משחרר אותה.','Requesting…'=>'שולח בקשה…','Restart registration'=>'התחלת ההרשמה מחדש','Restore code'=>'קוד שחזור','Restore purchase'=>'שחזור רכישה','Retry request'=>'נסה לשלוח את הבקשה שוב','Roll back'=>'חזור לגרסה קודמת','Roll back and report'=>'שחזור לגרסה קודמת ושליחת דיווח','Roll back and send report'=>'שחזור לגרסה קודמת ושליחת דיווח','Roll back the %2$s translation of %1$s to the previous build?'=>'לשחזר את התרגום ל-%2$s של %1$s לבנייה הקודמת?','Rolled back and reported.'=>'בוצעה חזרה לגרסה הקודמת והדיווח נשלח.','Rolled back to the previous build.'=>'בוצעה חזרה לגרסה הקודמת.','Rolled back, but the report could not be sent: %s'=>'בוצעה חזרה לגרסה הקודמת, אך לא ניתן היה לשלוח את הדיווח: %s','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'שחזור לגרסה קודמת ידרוס את \'%1$s\' (%2$s), שמוגש כעת עבור רכיב מותקן אחר (%3$s). דבר לא שונה.','Rotate-token response was missing site_token.'=>'בתגובה להחלפת האסימון חסר site_token.','Save changes'=>'שמירת שינויים','Scheduled, waiting to be processed'=>'מתוזמן, ממתין לעיבוד','Search'=>'חיפוש','Search components'=>'חיפוש רכיבים','Search the installed translations'=>'חיפוש בתרגומים המותקנים','Select all'=>'בחירת הכול','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'יש לבחור פחות רכיבים: לכל היותר %1$d פעולות בכל הרצה (בחרת %2$d).','Send report'=>'שליחת דיווח','Service plan'=>'תוכנית שירות','Settings'=>'הגדרות','Share error reports'=>'שיתוף דוחות שגיאה','Share this report'=>'שיתוף הדוח הזה','Show a new restore code'=>'הצגת קוד שחזור חדש','Show the "Report translation" entry in the admin toolbar'=>'הצגת הפריט ״דיווח על תרגום״ בסרגל הכלים של הניהול','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'חלק מהטקסט ברכיב זה מקודד על ידי היוצר שלו ולא ניתן לתרגם אותו באמצעות חבילת שפה.','Status'=>'סטטוס','Status unknown'=>'הסטטוס אינו ידוע','String context'=>'הקשר המחרוזת','Suggested translation'=>'תרגום מוצע','Supplementary translation index'=>'אינדקס תרגומים משלימים','Supplementary translation index rebuilt.'=>'אינדקס התרגומים המשלים נבנה מחדש.','Supplementary translation maintenance'=>'תחזוקת תרגומים משלימים','Supplementary translations'=>'תרגומים משלימים','Sweep aborted without orphaning anything: %s.'=>'הסריקה בוטלה מבלי להפוך דבר ליתום: %s.','Sweep complete: %d file deleted.'=>'הסריקה הושלמה: %d קובץ נמחק.' . "\0" . 'הסריקה הושלמה: %d קבצים נמחקו.','Sweep now'=>'סרוק עכשיו','Sync complete.'=>'הסנכרון הושלם.','Thank you. Your report was sent.'=>'תודה. הדיווח שלך נשלח.','That component is not installed on this site, so a translation cannot be requested for it.'=>'הרכיב הזה אינו מותקן באתר זה, ולכן לא ניתן לבקש עבורו תרגום.','That does not look like a restore code.'=>'זה לא נראה כמו קוד שחזור.','That is not a valid WordPress locale code. Nothing was saved.'=>'זה אינו קוד שפה תקין של WordPress. דבר לא נשמר.','That is not a valid build identifier.'=>'זה אינו מזהה בנייה תקין.','That upload screen was out of date: a different upload has been prepared since. Nothing was sent. Review the current one from the Translations list.'=>'מסך ההעלאה הזה היה מיושן: מאז הוכנה העלאה אחרת. דבר לא נשלח. עיין בהעלאה הנוכחית ברשימת התרגומים.','The change could not be recorded in the translation index; please try again.'=>'לא ניתן היה לתעד את השינוי באינדקס התרגומים. נא לנסות שוב.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'הניקוי הורץ, אך חלק משינוייו לא נרשמו באינדקס התרגומים; הניקוי הבא ינסה שוב.','The component has no files that can be uploaded.'=>'אין ברכיב קבצים שניתן להעלות.','The component is not inside the plugins or themes directory.'=>'הרכיב אינו נמצא בתוך ספריית התוספים או ערכות הנושא.','The component\'s main file was not found.'=>'הקובץ הראשי של הרכיב לא נמצא.','The download response was missing a usable location.'=>'בתגובת ההורדה חסר מיקום שמיש.','The entry opens a panel to search the translations Babilim installed on this site and report one of them.'=>'הפריט פותח חלונית לחיפוש בתרגומים ש-Babilim התקין באתר זה ולדיווח על אחד מהם.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'השדה "%1$s" ארוך מדי: יש בו %2$d תווים והמגבלה היא %3$d. דבר לא נשלח; יש לקצר אותו ולנסות שוב.','The free service plan gives each site a limited number of slots for plugins and themes; the slots in use are shown in Settings after you enable Babilim.'=>'תוכנית השירות החינמית מקנה לכל אתר מספר מוגבל של מכסות לתוספים ולתבניות; המכסות שבשימוש מוצגות בהגדרות לאחר הפעלת Babilim.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'הדומיין שניתן \'%1$s\' אינו תואם לא ל-slug של ה-manifest של החבילה \'%2$s\' ולא ל-text_domain שלה \'%3$s\'.','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'האינדקס המאוחד עבור \'%s\' נבנה מחדש, אך אינדקס התרגומים לא הצליח לתעד אותו; הבנייה מחדש הבאה תנסה שוב.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'הטקסט המקורי והתרגומים שנוצרו ממנו יסופקו לאתרים אחרים שמתקינים את אותה גרסה.','The package declares no main translation file.'=>'החבילה אינה מצהירה על קובץ תרגום ראשי.','The package has no %s for its own text domain.'=>'לחבילה אין %s עבור ה-text domain של עצמה.','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'סוג ה-manifest של החבילה \'%1$s\' אינו תואם לסוג המבוקש \'%2$s\'.','The package produced no servable main translation file.'=>'החבילה לא יצרה קובץ תרגום ראשי שניתן להגשה.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'ה-text domain של החבילה \'%1$s\' אינו תואם לעותק של הרכיב באתר הזה (\'%2$s\'), ולכן היא לא הותקנה.','The packaged component could not be read.'=>'לא ניתן היה לקרוא את הרכיב הארוז.','The registration challenge is not in the expected form.'=>'אתגר הרישום אינו בפורמט הצפוי.','The report could not be sent.'=>'לא ניתן היה לשלוח את הדוח.','The search could not be completed.'=>'לא ניתן היה להשלים את החיפוש.','The service asked this site to wait before syncing again.'=>'השירות ביקש מהאתר הזה להמתין לפני הסנכרון הבא.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'השירות לא הצליח להגיע לאתר שלך. ככל הנראה חומת אש, תוסף אבטחה או כלל אצל חברת האחסון חוסמים את הבקשה; יש לאפשר בקשות אל /wp-json/babilim/v1/challenge.','The service\'s upload offer was incomplete.'=>'הצעת ההעלאה של השירות הייתה חלקית.','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'ה-text domain‏ \'%1$s\' (%2$s) כבר מוגש עבור רכיב מותקן אחר (%3$s). דבר לא הותקן.','The upload is kept until you ask Babilim to delete it.'=>'ההעלאה נשמרת עד שתבקשו מ-Babilim למחוק אותה.','Theme'=>'תבנית','Theme · %s'=>'תבנית · %s','Themes'=>'תבניות','There is no upload in progress.'=>'אין העלאה בתהליך.','There is no upload waiting for confirmation.'=>'אין העלאה הממתינה לאישור.','These are the languages this site uses. You can change them in %s.'=>'אלו השפות שבהן האתר משתמש. אפשר לשנות אותן ב־%s.','These fields will be sent:'=>'השדות האלה יישלחו:','This build is not one this site currently knows about for this component/locale.'=>'גרסה זו אינה גרסה שהאתר מכיר כעת עבור הרכיב/השפה הזה.','This component does not declare a version number, so a translation cannot be requested for it.'=>'הרכיב הזה אינו מצהיר על מספר גרסה, ולכן לא ניתן לבקש עבורו תרגום.','This component is larger than the service accepts, so it cannot be uploaded.'=>'הרכיב הזה גדול מהמותר בשירות, ולכן אי אפשר להעלות אותו.','This component was already uploaded. Babilim is checking it now.'=>'הרכיב הזה כבר הועלה. Babilim בודק אותו כעת.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'מספר הגרסה של הרכיב הזה ארוך מ-%d תווים, ש-Babilim אינו יכול לטפל בהם, ולכן לא ניתן לבקש עבורו תרגום.','This issues a new restore code and the previous one stops working. Continue?'=>'פעולה זו תנפיק קוד שחזור חדש והקוד הקודם יפסיק לעבוד. להמשיך?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'ברשת זו יש יותר מדי אתריםכדי לבדוק אותם אחד אחד, ויתכן שחלקם מוגדרים למחוק את זהות Babilim שלהם כאשר התוסף נמחק. לא ניתן יהיה לשחזר אוטומטית את הרישיון בתשלום המקושר לאתר כזה; יהיה עליך לפנות לתמיכה של Babilim בכתובת %s. כדי לשמור על הזהויות, לחץ על ביטול, בטל את הסימון של "מחק את כל נתוני Babilim בעת הסרת ההתקנה" בהגדרות Babilim של כל אתר, והשבת שוב. להשבית בכל זאת?','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'גרסת התוסף עצמו, כדי שהשירות יוכל להורות לך לעדכן אותו אם הוא ישן מדי לתקשורת.','This report does not name a valid plugin or theme and locale.'=>'הדיווח הזה אינו כולל שם תקין של תוסף או תבנית ושפה.','This report does not name an installed string.'=>'הדוח הזה לא מציין שם של מחרוזת מותקנת.','This report is missing a valid build to report against.'=>'בדיווח זה חסרה גרסה תקפה שעליה ניתן לדווח.','This report will be posted publicly on GitHub and may be kept by third parties.'=>'הדוח הזה יפורסם בפומבי ב-GitHub ועשוי להישמר בידי צדדים שלישיים.','This restore code was not recognised for this site.'=>'קוד השחזור הזה לא זוהה עבור האתר הזה.','This site already has an active registration that can no longer be recovered automatically.'=>'לאתר זה כבר יש הרשמה פעילה שאי אפשר עוד לשחזר אוטומטית.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'באתר הזה יש %1$d רכיבים ב-%2$d שפות, מה שדורש %3$d מנות בדיקה; Babilim יכול לטפל במקסימום %4$d בכל הרצה. הפחת את השפות המנוהלות ב"הגדרות" או השבת תוספים וערכות נושא שאינם בשימוש, ואז לחץ על "בדוק שוב עכשיו".','This site has no purchase to show a code for.'=>'לאתר הזה אין רכישה שניתן להציג עבורה קוד.','This site is already licensed. Reload the page.'=>'לאתר זה כבר יש רישיון. יש לרענן את העמוד.','This site is not registered with Babilim yet.'=>'אתר זה עדיין לא רשום ב-Babilim.','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'האתר הזה חורג מהגודל שהשירות מקבל בסנכרון אחד, ולכן חלק מהפריטים הושמטו: %1$d רכיבים ו-%2$d שפות.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'אתר זה הוא חלק מרשת רב-אתרים, שאינה מתקינה תרגומים חדשים אוטומטית. תרגומים שכבר מותקנים ימשיכו להתעדכן.','This site is verified.'=>'האתר הזה מאומת.','This site must be verified first.'=>'יש לאמת את האתר הזה תחילה.','This site\'s URL, so the service can verify you own it.'=>'כתובת ה-URL של האתר הזה, כדי שהשירות יוכל לוודא שהוא בבעלותך.','This site\'s address is too long for Babilim to register.'=>'כתובת האתר הזה ארוכה מדי ול-Babilim אין אפשרות לרשום אותה.','This site\'s configured locale.'=>'השפה (locale) שהוגדרה לאתר הזה.','This site\'s locale code is not one Babilim can register.'=>'קוד השפה של האתר הזה אינו קוד ש-Babilim יכול לרשום.','This string can\'t be reported from this site.'=>'לא ניתן לדווח על המחרוזת הזו מהאתר הזה.','This string is not among the translations installed on this site. Search again and pick it from the list.'=>'המחרוזת הזו אינה נמצאת בין התרגומים המותקנים באתר זה. חפש שוב ובחר אותה מהרשימה.','This translation was updated since you searched. Search again and pick the string from the new list.'=>'התרגום הזה עודכן מאז החיפוש שלך. חפש שוב ובחר את המחרוזת מהרשימה החדשה.','To translate this component, Babilim needs its source.'=>'כדי לתרגם את הרכיב הזה, Babilim זקוק לקוד המקור שלו.','Too many attempts. Try again tomorrow.'=>'יותר מדי ניסיונות. נסו שוב מחר.','Too many reports today. Try again tomorrow.'=>'יותר מדי דיווחים היום. נסו שוב מחר.','Too many requests.'=>'יותר מדי בקשות.','Toolbar'=>'סרגל הכלים','Translating…'=>'מתרגם…','Translation does not load'=>'התרגום אינו נטען','Translation failed'=>'התרגום נכשל','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'קובצי תרגום שתניחו ב-%s תמיד מקבלים עדיפות על פני אלה של Babilim. הם נשמרים אלא אם תבטלו את הסימון.','Translation requested.'=>'התרגום התבקש.','Translations'=>'תרגומים','Type'=>'סוג','Type at least 2 characters to search.'=>'יש להקליד לפחות 2 תווים כדי לבצע חיפוש.','Unexpected HTTP %d response.'=>'תגובת HTTP בלתי צפויה %d.','Uninstall'=>'הסרת התקנה','Unknown kind: %s'=>'סוג לא מוכר: %s','Unsafe domain: %s'=>'דומיין לא בטוח: %s','Unsafe locale: %s'=>'שפה (locale) לא בטוחה: %s','Unsafe slug: %s'=>'slug לא בטוח: %s','Unsafe text_domain: %s'=>'text_domain לא בטוח: %s','Update'=>'עדכון','Update available'=>'קיים עדכון','Updates'=>'עדכונים','Updating…'=>'מעדכן…','Upgrade this site'=>'שדרוג האתר הזה','Upload and request'=>'העלאה ובקשה','Upload cancelled.'=>'ההעלאה בוטלה.','Upload complete — translation requested.'=>'ההעלאה הושלמה — התרגום התבקש.','Upload expired before it finished'=>'ההעלאה פגה לפני שהסתיימה','Upload in progress — continue or cancel'=>'העלאה בתהליך — המשך או ביטול','Upload this component?'=>'להעלות את הרכיב הזה?','Upload was not accepted'=>'ההעלאה לא התקבלה','Uploading'=>'מעלה','Uploading part %1$d of %2$d…'=>'מעלה חלק %1$d מתוך %2$d…','Uploading…'=>'מעלה…','Verified'=>'אומת','Verify response was missing site_token.'=>'בתגובת האימות חסר site_token.','Version %s'=>'גרסה %s','What is sent when you enable Babilim'=>'מה נשלח בעת הפעלת Babilim','When something fails inside Babilim, send an error report to the Babilim service so it can be published as a public issue on GitHub. The report is sent as coming from this site, with the same authentication as every other request to the Babilim service. The service publishes only the error code and versions as a public issue on GitHub; the public issue contains no site address, content or file paths. Off by default.'=>'כאשר משהו נכשל בתוך Babilim, יישלח דוח שגיאה אל שירות Babilim כדי שניתן יהיה לפרסמו כבעיה ציבורית ב-GitHub. הדוח נשלח כאילו הגיע מהאתר הזה, עם אותו אימות כמו כל בקשה אחרת אל שירות Babilim. השירות מפרסם כבעיה ציבורית ב-GitHub רק את קוד השגיאה והגרסאות; הבעיה הציבורית אינה כוללת כתובת אתר, תוכן או נתיבי קבצים. כבוי כברירת מחדל.','Where you saw this (optional)'=>'איפה ראית זאת (אופציונלי)','While this is on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'כשהאפשרות פעילה, תרגומים שהשירות מציין כזמינים עבור השפות שבהן אתה משתמש מותקנים במהלך סנכרון פעמיים ביום.','WordPress.org'=>'WordPress.org','Wrong for this context'=>'שגוי להקשר הזה','Wrong meaning'=>'משמעות שגויה','Wrong plural form'=>'צורת רבים שגויה','Wrong term'=>'מונח שגוי','Yes'=>'כן','You are not allowed to do this.'=>'אין לך הרשאה לבצע פעולה זו.','Your PHP version, for compatibility.'=>'גרסת ה-PHP שלך, לצורכי תאימות.','Your WordPress version, to serve compatible translation files.'=>'גרסת ה-WordPress שלך, כדי לספק קובצי תרגום תואמים.','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'קוד השחזור החדש שלכם: %s. שמרו אותו במקום בטוח — הקוד הקודם אינו עובד עוד.','Your report is processed automatically by AI models and may improve this translation for other sites.'=>'הדיווח שלך מעובד אוטומטית על ידי מודלי AI ועשוי לשפר את התרגום הזה עבור אתרים אחרים.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'האתר שלך הגיב, אך לא בתשובה הצפויה. ייתכן שה-REST API נכתב מחדש על ידי תוסף אחר, או שנקודת הקצה הזו נשמרת במטמון; יש להחריג את /wp-json/babilim/v1/challenge ממטמון וכתיבה מחדש.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'האתר שלכם ענה לאט מדי. נסו שוב מאוחר יותר, ובדקו שהאחסון שלכם אינו איטי או עמוס מדי.','Zip has no manifest.json.'=>'אין ב-zip קובץ manifest.json.','Zip is missing expected default file: %s'=>'קובץ ברירת מחדל נדרש חסר בקובץ ה-Zip: %s','Zip is missing expected file: %s'=>'קובץ נדרש חסר בקובץ ה-Zip: %s','_manifest.json has an unexpected structure'=>'ל־_manifest.json יש מבנה בלתי צפוי','could not read _manifest.json: %s'=>'לא ניתן היה לקרוא את _manifest.json: %s','expected_manifest is missing or has an invalid \'%s\'.'=>'השדה \'%s\' ב-expected_manifest חסר או לא תקין.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'השדה \'server_build_id\' ב-expected_manifest אינו מזהה בנייה תקין.','failed to parse _manifest.json: %s'=>'הניתוח של _manifest.json נכשל: %s','it would orphan %1$d of %2$d managed components (more than half)'=>'הדבר יהפוך ליתומים %1$d מתוך %2$d רכיבים מנוהלים (יותר ממחציתם)','it would orphan every managed %1$s component (%2$d of %2$d)'=>'הדבר יהפוך ליתום כל רכיב מסוג %1$s מנוהל (%2$d מתוך %2$d)','l10n.php entry count mismatch for %s'=>'אי-התאמה במספר הרשומות ב-l10n.php עבור %s','manifest.json has an invalid \'default_domain_entries\'.'=>'השדה \'default_domain_entries\' ב-manifest.json אינו תקין.','manifest.json has an invalid \'default_domain_files\'.'=>'השדה \'default_domain_files\' ב-manifest.json אינו תקין.','manifest.json in the zip is not valid JSON.'=>'הקובץ manifest.json שב-zip אינו JSON תקין.','manifest.json is missing or has an invalid \'%s\'.'=>'השדה \'%s\' חסר או לא תקין ב-manifest.json.','manifest.json is missing or has an invalid \'build_no\'.'=>'השדה \'build_no\' חסר או לא תקין ב-manifest.json.','manifest.json is missing or has an invalid \'entries\'.'=>'השדה \'entries\' חסר או לא תקין ב-manifest.json.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'השדה \'extra_domains\' חסר או לא תקין ב-manifest.json.','manifest.json is missing or has an invalid \'files\'.'=>'השדה \'files\' חסר או לא תקין ב-manifest.json.','manifest.json\'s \'%s\' does not match the expected value.'=>'השדה \'%s\' ב-manifest.json אינו תואם לערך הצפוי.','manifest.json\'s \'contract\' is not a valid version string.'=>'השדה \'contract\' ב-manifest.json אינו מחרוזת גרסה תקינה.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'הערך של \'kind\' ב-manifest.json חייב להיות \'plugin\' או \'theme\'.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'השדה \'server_build_id\' ב-manifest.json אינו מזהה בנייה תקין.','manifest.json\'s \'status\' must be \'published\'.'=>'הערך של \'status\' ב-manifest.json חייב להיות \'published\'.','nonce must be a hexadecimal string.'=>'nonce חייב להיות מחרוזת הקסדצימלית.','per day'=>'ליום','rc_…'=>'rc_…','sha256 mismatch for %s'=>'אי-התאמת sha256 עבור %s','sha256 mismatch for default/%s'=>'אי-התאמת sha256 עבור default/%s','component kind in the sweep brake messageplugin'=>'תוסף','component kind in the sweep brake messagetheme'=>'תבנית','problem report categoryOther'=>'אחר','translation statusAvailable'=>'זמין','translation statusInstalled'=>'מותקן']];